import { describe, expect, it } from 'vitest';
import {
  LETTER_VALUES,
  computeCheckDigit,
  formatContainerNumber,
  isValidContainerNumber,
  normalise,
  parseContainerNumber,
  validateContainerNumber,
} from './check-digit.js';

// Generated by a separate Python implementation of the standard, so these do
// not just repeat the TypeScript logic back to itself. CSQU3054383 is the
// example from the standard and from the system plan.
const VALID = [
  'CSQU3054383',
  'MSKU9070323',
  'MSCU6639870',
  'TGHU1234567',
  'HLXU8765430',
  'CMAU0000010',
  'OOLU1548228',
  'MAEU8001232',
  'TCNU1122333',
  'APZU4690114',
  'GESU5200048',
];

describe('LETTER_VALUES', () => {
  it('matches the values in the standard', () => {
    expect(LETTER_VALUES.A).toBe(10);
    expect(LETTER_VALUES.B).toBe(12);
    expect(LETTER_VALUES.K).toBe(21);
    expect(LETTER_VALUES.L).toBe(23);
    expect(LETTER_VALUES.U).toBe(32);
    expect(LETTER_VALUES.V).toBe(34);
    expect(LETTER_VALUES.Z).toBe(38);
  });

  it('never uses a multiple of 11', () => {
    for (const v of Object.values(LETTER_VALUES)) expect(v % 11).not.toBe(0);
  });
});

describe('computeCheckDigit', () => {
  it.each(VALID)('gives the right digit for %s', (n) => {
    expect(computeCheckDigit(n.slice(0, 10))).toBe(Number(n[10]));
  });

  it('maps a remainder of 10 to 0', () => {
    // CSQU100008 sums to a remainder of 10 under mod 11 (checked in Python).
    expect(computeCheckDigit('CSQU100008')).toBe(0);
    expect(isValidContainerNumber('CSQU1000080')).toBe(true);
  });

  it('rejects bad shapes', () => {
    expect(() => computeCheckDigit('CSQ305438')).toThrow();
    expect(() => computeCheckDigit('CSQU30543A')).toThrow();
  });
});

describe('isValidContainerNumber', () => {
  it.each(VALID)('accepts %s', (n) => {
    expect(isValidContainerNumber(n)).toBe(true);
  });

  it('accepts spaces, dashes and lower case', () => {
    expect(isValidContainerNumber('csqu 305438-3')).toBe(true);
  });

  it('rejects a wrong check digit', () => {
    expect(isValidContainerNumber('CSQU3054384')).toBe(false);
  });

  it('rejects a category letter other than U, J or Z', () => {
    expect(isValidContainerNumber('CSQA3054383')).toBe(false);
  });

  it('rejects wrong lengths and empty input', () => {
    expect(isValidContainerNumber('')).toBe(false);
    expect(isValidContainerNumber('CSQU305438')).toBe(false);
    expect(isValidContainerNumber('CSQU30543833')).toBe(false);
  });
});

describe('validateContainerNumber', () => {
  it('explains a bad check digit and gives the expected digit', () => {
    expect(validateContainerNumber('CSQU3054389')).toEqual({
      ok: false,
      value: 'CSQU3054389',
      reason: 'check_digit',
      expectedCheckDigit: 3,
    });
  });

  it('flags the category letter', () => {
    expect(validateContainerNumber('CSQX3054383')).toMatchObject({ ok: false, reason: 'category' });
  });

  it('flags the format', () => {
    expect(validateContainerNumber('12345')).toMatchObject({ ok: false, reason: 'format' });
  });

  it('returns the cleaned value when valid', () => {
    expect(validateContainerNumber(' csqu-305438 3 ')).toEqual({ ok: true, value: 'CSQU3054383' });
  });
});

describe('helpers', () => {
  it('normalises', () => {
    expect(normalise(' cs-qu 30.5438/3 ')).toBe('CSQU3054383');
  });

  it('parses parts', () => {
    expect(parseContainerNumber('CSQU3054383')).toEqual({
      ownerCode: 'CSQ',
      category: 'U',
      serial: '305438',
      checkDigit: 3,
    });
    expect(parseContainerNumber('nope')).toBeNull();
  });

  it('formats for display', () => {
    expect(formatContainerNumber('csqu3054383')).toBe('CSQU 305438 3');
    expect(formatContainerNumber('bad')).toBe('bad');
  });
});
